'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allQuestions=topics.flatMap(t=>t.questions),byId=new Map(allQuestions.map(q=>[q.id,q])),byTopic=new Map(topics.map(t=>[t.id,t]));
const state={section:'1.1',topic:'all',type:'all',scope:'section',cart:[],title:'七年级上册数学练习卷',space:'normal',mode:'student',examples:false};
try{const saved=JSON.parse(localStorage.getItem('xunti-paper-v1')||'null');if(saved&&typeof saved==='object'){state.cart=Array.isArray(saved.cart)?[...new Set(saved.cart.filter(id=>byId.has(id)))]:[];if(typeof saved.title==='string')state.title=saved.title.slice(0,80);if(['compact','normal','large'].includes(saved.space))state.space=saved.space;}}catch{}
function save(){try{localStorage.setItem('xunti-paper-v1',JSON.stringify({cart:state.cart,title:state.title,space:state.space}));}catch{toast('浏览器未允许保存草稿，请在关闭页面前打印。');}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',2500);}
function sectionName(section){const [c,s]=section.split('.').map(Number);return s===0?'单元复习与综合训练':curriculum[c-1].sections[s-1];}
function currentTopics(){return topics.filter(t=>t.section===state.section);}
function filtered(){return allQuestions.filter(q=>(state.scope==='book'||(state.scope==='chapter'?q.chapter===Number(state.section.split('.')[0]):q.section===state.section))&&(state.topic==='all'||q.topicId===state.topic)&&(state.type==='all'||q.type===state.type));}
function navigate(section){if(!topics.some(t=>t.section===section))throw Error('无此章节');state.section=section;state.topic='all';state.scope='section';state.type='all';render();window.scrollTo({top:0,behavior:'smooth'});}
function renderNav(){const chapter=Number(state.section.split('.')[0]);$('#chapters').innerHTML=curriculum.map((c,i)=>`<div class="chapter ${chapter===i+1?'selected':''}"><button data-act="chapter" data-id="${i+1}" aria-expanded="${chapter===i+1}"><span class="chapter-num">0${i+1}</span>${esc(c.name)}</button>${chapter===i+1?`<div class="sections">${[...c.sections,'单元复习'].map((s,j)=>{const key=`${i+1}.${j===c.sections.length?0:j+1}`;return `<button data-act="section" data-id="${key}" class="${key===state.section?'current':''}" ${key===state.section?'aria-current="page"':''}>${j===c.sections.length?'↳':j+1+'.'} ${esc(s)}</button>`;}).join('')}</div>`:''}</div>`).join('');}
function render(){renderNav();const chapter=Number(state.section.split('.')[0]),list=currentTopics(),active=byTopic.get(state.topic)||list[0];const qCount=list.reduce((n,t)=>n+t.questions.length,0);$('#main').innerHTML=`
<div class="breadcrumb">数学七上 <span>/</span> 第${'一二三四五六'[chapter-1]}章 ${esc(curriculum[chapter-1].name)} <span>/</span> ${esc(sectionName(state.section))}</div>
<div class="title-row"><div><p class="eyebrow">CHAPTER 0${chapter} <span class="edition-tag">教材同步 · 完整题库</span></p><h1>${esc(sectionName(state.section))}</h1><p class="muted">${list.length} 个知识点/专题 · ${qCount} 道可选题目</p></div><span class="chapter-symbol" aria-hidden="true">${['△','⋈','∟','√','⊕','↗'][chapter-1]}</span></div>
<div class="mobile-section"><label for="section-select">教材节次</label><select id="section-select">${curriculum.flatMap((c,i)=>[...c.sections,'单元复习'].map((s,j)=>{const value=`${i+1}.${j===c.sections.length?0:j+1}`;return `<option value="${value}" ${value===state.section?'selected':''}>${i+1}.${j===c.sections.length?'复习':j+1} ${esc(s)}</option>`;})).join('')}</select></div>
<div class="lesson-tabs" aria-label="知识点/专题"><button data-act="topic" data-id="all" class="${state.topic==='all'?'selected':''}" aria-pressed="${state.topic==='all'}">本节全部题型</button>${list.map((t,i)=>`<button data-act="topic" data-id="${t.id}" class="${state.topic===t.id?'selected':''}" aria-pressed="${state.topic===t.id}"><span>${String(i+1).padStart(2,'0')}</span>${esc(t.name)}</button>`).join('')}</div>
${active?`<section class="guide"><div><span class="pill">${state.topic==='all'?'知识点导读':'知识点 '+(list.indexOf(active)+1)}</span><h2>${esc(active.name)}</h2><p>${esc(active.rule)}</p></div><button data-act="example" data-id="${active.id}">知识与代表题 <span aria-hidden="true">↗</span></button></section>`:''}
<section class="bank"><div class="section-heading"><h2>题库 <span id="result-count"></span></h2><button class="text-button" data-act="coverage">查看全册题型目录</button></div><div class="filter-top"><label>选题范围 <select id="scope"><option value="section" ${state.scope==='section'?'selected':''}>当前节</option><option value="chapter" ${state.scope==='chapter'?'selected':''}>当前章</option><option value="book" ${state.scope==='book'?'selected':''}>全册</option></select></label><label>题目形式 <select id="type"><option value="all">全部形式</option>${['选择题','填空题','计算题','证明题','作图题','解答题'].map(t=>`<option ${state.type===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="text-button" data-act="select-visible">勾选当前结果</button></div><div id="questions"></div></section><p class="content-note">${topics.length} 个知识点/专题 · ${allQuestions.length} 道可选题目。第一章按用户提供材料全量整理并保留原题图；不再设置难度标签，由家长自行选题。</p>`;renderQuestions();renderCount();}
function renderQuestions(){const list=filtered();$('#result-count').textContent=`${list.length} 题`;$('#questions').innerHTML=list.length?list.map(q=>questionCard(q)).join(''):`<div class="empty"><h3>当前条件下没有题目</h3><p>可切换题目形式或扩大选题范围。</p><button data-act="reset-filters">重置筛选</button></div>`;}
function optionsHTML(q){return q.options?.length?`<div class="options-grid">${q.options.map((v,i)=>`<div><b>${'ABCD'[i]}.</b> ${esc(v)}</div>`).join('')}</div>`:'';}
function figureHTML(q){if(q.figure?.src)return `<figure class="source-figure"><img src="${esc(q.figure.src)}" alt="${esc(q.figure.alt||'题目原图')}" loading="lazy"><figcaption>${esc(q.source||'原材料题图')}</figcaption></figure>`;return q.diagram?drawDiagram(q.diagram):'';}
function questionCard(q){const t=byTopic.get(q.topicId),picked=state.cart.includes(q.id);return `<article class="question ${picked?'picked':''}" data-question-id="${q.id}"><div class="q-meta"><span>${q.type}</span>${q.source?`<span class="q-source">${esc(q.source)}</span>`:''}<span class="q-topic">${esc(t.name)}</span><span class="q-id">${esc(q.id.toUpperCase())}</span></div><p>${esc(q.text)}</p>${figureHTML(q)}${optionsHTML(q)}<div class="q-bottom"><div><button data-act="answer" data-id="${q.id}">查看解析</button><button class="text-button" data-act="example" data-id="${t.id}">知识点说明</button></div><label class="pick ${picked?'selected':''}"><input type="checkbox" data-pick="${q.id}" ${picked?'checked':''}><span>${picked?'已加入练习卷':'加入练习卷'}</span></label></div></article>`;}
function renderCount(){$('#cart-count').textContent=state.cart.length;}
function setPicked(ids,selected){if(!Array.isArray(ids)||ids.some(id=>!byId.has(id)))throw Error('题目编号无效');state.cart=selected?[...new Set([...state.cart,...ids])]:state.cart.filter(id=>!ids.includes(id));save();renderCount();renderQuestions();}
function showDialog(selector,html){const dialog=$(selector);dialog.innerHTML=html;if(!dialog.open)dialog.showModal();}
const dialogHead=(title,subtitle='')=>`<div class="dialog-head"><div><h2>${esc(title)}</h2>${subtitle?`<p class="muted">${esc(subtitle)}</p>`:''}</div><button data-act="close" aria-label="关闭">×</button></div>`;
function solutionHTML(q){return `<div class="solution"><strong>答案：${esc(q.answer)}</strong><ol>${(q.steps||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div>`;}
function showExample(id){const t=byTopic.get(id);if(!t)return;showDialog('#detail',dialogHead(t.name,`${t.questions.length} 道可选题目`)+`<div class="knowledge"><h3>知识要点</h3><p>${esc(t.rule)}</p><h3>解题方法</h3><p>${esc(t.method)}</p><div class="pitfall"><strong>易错提醒</strong> ${esc(t.pitfall)}</div></div><div class="example"><span class="pill">代表题 · ${esc(t.example.type)}</span>${t.example.source?`<p class="muted">${esc(t.example.source)}</p>`:''}<p>${esc(t.example.text)}</p>${figureHTML(t.example)}${optionsHTML(t.example)}${solutionHTML(t.example)}</div><div class="dialog-actions"><button class="primary" data-act="practice" data-id="${id}">查看本题型全部题目</button></div>`);}
function showAnswer(id){const q=byId.get(id);showDialog('#detail',dialogHead('答案与解析',`${q.source?`${q.source} · `:''}${byTopic.get(q.topicId).name}`)+`<p>${esc(q.text)}</p>${figureHTML(q)}${optionsHTML(q)}${solutionHTML(q)}<div class="pitfall"><strong>方法提示</strong> ${esc(byTopic.get(q.topicId).method)}</div>`);}
function showCoverage(){showDialog('#detail',dialogHead('全册题型目录',`${topics.length} 个知识点/专题 · ${allQuestions.length} 道可选题目`)+`<div class="coverage">${curriculum.map((c,i)=>`<h3>第${'一二三四五六'[i]}章 ${esc(c.name)}</h3>${[...c.sections,'单元复习'].map((s,j)=>{const key=`${i+1}.${j===c.sections.length?0:j+1}`,ts=topics.filter(t=>t.section===key);return `<details><summary>${j===c.sections.length?'复习':j+1} ${esc(s)} <span>${ts.length} 个题型 · ${ts.reduce((n,t)=>n+t.questions.length,0)} 题</span></summary><ul>${ts.map(t=>`<li><button class="text-button" data-act="coverage-topic" data-id="${t.id}">${esc(t.name)}（${t.questions.length}题） ↗</button></li>`).join('')}</ul></details>`;}).join('')}`).join('')}<p class="muted">第一章按完整材料归类收录；其余章节保持现有题库，后续可按同样方式扩充。</p></div>`);}
function typeSummary(list){const order=['选择题','填空题','计算题','证明题','作图题','解答题'];return order.map(t=>[t,list.filter(q=>q.type===t).length]).filter(([,n])=>n).map(([t,n])=>`${t} ${n}`).join(' · ');}
function renderPaper(){const list=state.cart.map(id=>byId.get(id));showDialog('#paper',dialogHead('我的练习卷',`${list.length} 题 · 草稿保存在当前浏览器`)+`<div class="paper-settings"><label>练习卷标题<input id="paper-title" maxlength="80" value="${esc(state.title)}"></label><div class="paper-setting-row"><label>输出内容<select id="paper-mode"><option value="student" ${state.mode==='student'?'selected':''}>学生练习卷</option><option value="answers" ${state.mode==='answers'?'selected':''}>家长答案解析卷</option></select></label><label>作答留白<select id="paper-space">${[['compact','紧凑'],['normal','标准'],['large','宽松']].map(([v,t])=>`<option value="${v}" ${state.space===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="inline-check"><input id="paper-examples" type="checkbox" ${state.examples?'checked':''}>附所选知识点的代表题讲解</label></div></div><div class="paper-toolbar"><button data-act="sort-paper" ${!list.length?'disabled':''}>按题目形式整理</button><span class="muted">${esc(typeSummary(list)||'尚未选题')}</span></div><div class="paper-items">${list.length?list.map((q,i)=>`<div class="paper-item"><strong>${i+1}</strong><div><span class="muted">${esc(q.type)} · ${esc(byTopic.get(q.topicId).name)}${q.source?` · ${esc(q.source)}`:''}</span><p>${esc(q.text)}</p></div><div class="order-buttons"><button data-act="up" data-id="${q.id}" aria-label="上移第 ${i+1} 题" ${i===0?'disabled':''}>↑</button><button data-act="down" data-id="${q.id}" aria-label="下移第 ${i+1} 题" ${i===list.length-1?'disabled':''}>↓</button><button data-act="remove" data-id="${q.id}" aria-label="移除第 ${i+1} 题">×</button></div></div>`).join(''):`<div class="empty"><h3>练习卷还是空的</h3><p>从题库勾选题目，可跨章节加入同一份练习卷。</p><button data-act="close">返回选题</button></div>`}</div><div class="dialog-actions paper-footer"><span class="muted">A4 排版 · 学生卷不含答案</span><button data-act="preview-paper" ${!list.length?'disabled':''}>排版预览</button><button data-act="print" ${!list.length?'disabled':''}>打印</button><button class="primary" data-act="pdf" ${!list.length?'disabled':''}>下载 PDF</button><p class="print-hint">若没有弹出打印窗口，请下载 PDF，再用 PDF 阅读器打印。</p></div>`);}
function printHTML(){const list=state.cart.map(id=>byId.get(id)),answer=state.mode==='answers',title=(state.title.trim()||'数学练习卷')+(answer?' · 答案解析':'');const lessons=[...new Set(list.map(q=>q.topicId))].map(id=>byTopic.get(id));return `<div class="paper-document ${state.space}"><h1>${esc(title)}</h1><div class="print-meta">鲁教版五四制 · 七年级上册数学　共 ${list.length} 题</div>${answer?'':'<div class="student-line">姓名：________________　日期：________________</div>'}${state.examples?`<section class="printed-examples"><h2>知识点代表题</h2>${lessons.map(t=>`<article class="print-example"><h3>${esc(t.name)}</h3><p>${esc(t.rule)}</p><p><strong>代表题：</strong>${esc(t.example.text)}</p>${figureHTML(t.example)}${optionsHTML(t.example)}${solutionHTML(t.example)}</article>`).join('')}</section><h2 class="exercise-start">${answer?'练习答案':'练习题'}</h2>`:''}${list.map((q,i)=>`<article class="print-question"><div class="print-q-title"><b>${i+1}.</b><span>${esc(q.text)}</span></div>${q.source?`<div class="muted">来源：${esc(q.source)}</div>`:''}${figureHTML(q)}${optionsHTML(q)}${answer?solutionHTML(q):`<div class="answer-space ${['选择题','填空题'].includes(q.type)?'short':''}" aria-label="作答区域"></div>`}</article>`).join('')}<div class="print-end">— ${answer?'答案解析':'练习卷'}结束 —</div></div>`;}
let pdfBusy=false,printDialogs=[];
async function previewPaper(download=false){if(!state.cart.length||pdfBusy)return;const paper=structuredClone({title:(state.title.trim()||'数学练习卷')+(state.mode==='answers'?' · 答案解析':''),answer:state.mode==='answers',space:state.space,examples:state.examples,questions:state.cart.map(id=>byId.get(id)),lessons:[...new Set(state.cart.map(id=>byId.get(id).topicId))].map(id=>byTopic.get(id))});const readable=printHTML(),filename=paper.title.replace(/[\\/:*?"<>|]/g,'_')+'.pdf';pdfBusy=true;showDialog('#detail',dialogHead('正在生成 PDF')+'<p id="pdf-progress" role="status">正在排版，请稍候…</p>');const progress=$('#pdf-progress');try{const result=await PaperPDF.create(paper,(n,total)=>{if(progress.isConnected)progress.textContent=`正在生成第 ${n} / ${total} 页…`;});if(!$('#detail').open)return;showDialog('#detail',dialogHead('PDF 已生成',`${paper.answer?'家长答案解析卷':'学生练习卷'} · A4 · ${result.pages} 页`)+`<div class="pdf-actions"><a class="primary download-link" id="pdf-download" href="${result.dataUrl}" download="${esc(filename)}">下载 PDF（${result.pages} 页）</a><button data-act="print">打印</button></div><p class="muted">题目原图会随题目进入 PDF。以下为实际分页预览。</p><div class="pdf-pages">${result.images.map((p,i)=>`<figure><img src="${p.data}" alt="${esc(paper.title)}，第 ${i+1} 页" loading="lazy"><figcaption>第 ${i+1} 页 / 共 ${result.pages} 页</figcaption></figure>`).join('')}</div><details class="pdf-readable"><summary>查看可复制的文字版</summary>${readable}</details>`);if(download)$('#pdf-download').click();}catch(error){if($('#detail').open)showDialog('#detail',dialogHead('PDF 暂未生成')+`<p role="alert">${esc(error.message||'导出失败，请重试。')}</p><div class="dialog-actions"><button data-act="pdf">重新生成 PDF</button><button data-act="print">使用浏览器打印</button></div>`);}finally{pdfBusy=false;}}
function preparePrint(){$('#print-root').innerHTML=state.cart.length?printHTML():'<p>尚未勾选题目，请先在题库中选择练习。</p>';if(!printDialogs.length)printDialogs=[$('#paper'),$('#detail')].filter(d=>d.open);for(const dialog of printDialogs)if(dialog.open)dialog.close();document.body.classList.add('printing');}
function restorePrint(){document.body.classList.remove('printing');const dialogs=printDialogs;printDialogs=[];for(const dialog of dialogs)if(dialog.isConnected&&!dialog.open)dialog.showModal();}
function doPrint(){if(!state.cart.length)return;preparePrint();try{window.print();}catch{toast('当前环境未能打开打印窗口，请下载 PDF 后打印。');}finally{setTimeout(restorePrint,300);}}
window.addEventListener('beforeprint',preparePrint);window.addEventListener('afterprint',restorePrint);
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.pick){setPicked([el.dataset.pick],el.checked);return;}if(el.id==='type'){state.type=el.value;renderQuestions();}if(el.id==='scope'){state.scope=el.value;state.topic='all';render();}if(el.id==='section-select')navigate(el.value);if(el.id==='paper-mode')state.mode=el.value;if(el.id==='paper-space'){state.space=el.value;save();}if(el.id==='paper-examples')state.examples=el.checked;});
document.addEventListener('input',e=>{if(e.target.id==='paper-title'){state.title=e.target.value;save();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const {act,id}=b.dataset;if(act==='chapter')navigate(id+'.1');if(act==='section')navigate(id);if(act==='topic'){state.topic=id;state.scope='section';render();}if(act==='answer')showAnswer(id);if(act==='example')showExample(id);if(act==='close')b.closest('dialog').close();if(act==='coverage')showCoverage();if(act==='practice'||act==='coverage-topic'){b.closest('dialog').close();state.section=byTopic.get(id).section;state.topic=id;state.scope='section';state.type='all';render();}if(act==='select-visible'){const qs=filtered();setPicked(qs.map(q=>q.id),true);toast(qs.length?'已将当前 '+qs.length+' 道题加入练习卷':'当前没有可勾选的题目');}if(act==='reset-filters'){state.topic='all';state.type='all';render();}if(act==='up'||act==='down'){const i=state.cart.indexOf(id),j=i+(act==='up'?-1:1);if(j>=0&&j<state.cart.length){[state.cart[i],state.cart[j]]=[state.cart[j],state.cart[i]];save();renderPaper();}}if(act==='remove'){setPicked([id],false);renderPaper();}if(act==='sort-paper'){const rank=['选择题','填空题','计算题','证明题','作图题','解答题'];state.cart.sort((a,b)=>rank.indexOf(byId.get(a).type)-rank.indexOf(byId.get(b).type));save();renderPaper();}if(act==='preview-paper')previewPaper();if(act==='pdf')previewPaper(true);if(act==='print')doPrint();});
$('#open-paper').addEventListener('click',renderPaper);$('#detail').setAttribute('aria-label','题型讲解与预览');$('#paper').setAttribute('aria-label','我的练习卷');render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'list_math_questions',description:'读取当前筛选结果及已选题目编号。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('不接受额外参数');return {questions:filtered().map(q=>({id:q.id,topic:byTopic.get(q.topicId).name,type:q.type,source:q.source||null,text:q.text,hasFigure:!!q.figure})),selectedIds:[...state.cart]};}},{name:'stage_math_paper_questions',description:'按题目编号批量加入或移出当前练习卷草稿，不打印。',inputSchema:{type:'object',properties:{ids:{type:'array',items:{type:'string'},minItems:1},selected:{type:'boolean'}},required:['ids','selected'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Array.isArray(input.ids)||!input.ids.length||typeof input.selected!=='boolean'||Object.keys(input).some(k=>!['ids','selected'].includes(k)))throw Error('参数无效');setPicked(input.ids,input.selected);if($('#paper').open)renderPaper();return {selectedIds:[...state.cart],count:state.cart.length};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
